    end
    local speed=math.sqrt(v.X^2+v.Z^2)
    local maxAngle=native and native.MaxAngleNow or math.clamp(math.deg(math.atan(grip*wheelbase/math.max(speed^2,25)))*1.05+6,4.5,32)
    local normal=Vector3.new(0,1,0)
