        Font=Enum.Font.GothamBold,ClearTextOnFocus=false},row);corner(value,5)
    local track=make("TextButton",{Name="Track",Position=UDim2.fromOffset(1,37),Size=UDim2.new(1,-2,0,6),Text="",
